-- Can the current user see this record? SECURITY INVOKER, so the target table's own RLS decides (SCHEMA § RLS).
-- Stub for slice 1: each later slice adds a WHEN for its record type. Unknown types are invisible (fail closed).
CREATE FUNCTION app.can_see(rt record_type, rid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER
  RETURN CASE rt
    WHEN 'org' THEN rid = app.org_id()
    WHEN 'user' THEN EXISTS (SELECT 1 FROM member WHERE user_id = rid)
    ELSE false
  END;--> statement-breakpoint

-- An event is visible, and can be written, only when its record is.
CREATE POLICY record_visibility ON timeline_events AS RESTRICTIVE TO crm_app USING (app.can_see(record_type, record_id));
